type Player = { name: string; score: number };

export function competition_rank(players: Player[]): [number, string][] {
  const sorted = [...players].sort((a, b) => {
    if (a.score > b.score) return -1;
    if (a.score < b.score) return 1;

    const right = b.name[Symbol.iterator]();
    for (const leftChar of a.name) {
      const next = right.next();
      if (next.done) return 1;

      const difference =
        (leftChar.codePointAt(0) ?? 0) - (next.value.codePointAt(0) ?? 0);
      if (difference !== 0) return difference;
    }
    return right.next().done ? 0 : -1;
  });

  return sorted.map((p) => [
    1 + players.filter((q) => q.score > p.score).length,
    p.name,
  ]);
}

