fn door_lock(code: String, events: List[Key]) -> String {
  var state = "locked"
  let empty = take([code], 0)
  var buf = empty
  var fails = 0
  let size = str_len(code)
  for k in events {
    let kind = match k {
      Digit(_) => "digit",
      Enter => "enter",
      Clear => "clear",
    }
    let digit = match k {
      Digit(d) => to_string(d),
      _ => "",
    }
    if state == "open" {
      if kind == "enter" {
        state = "locked"
        buf = empty
      }
    } else if state == "locked" {
      if kind == "digit" {
        if len(buf) == size {
          buf = drop(buf, 1)
        }
        buf = append(buf, digit)
      } else if kind == "clear" {
        buf = empty
      } else {
        if join(buf, "") == code {
          state = "open"
          fails = 0
        } else {
          fails = fails + 1
          if fails >= 3 {
            state = "blocked"
          }
        }
        buf = empty
      }
    }
  }
  return state
}

