from __future__ import annotations

from typing import Generic, Literal, TypedDict, TypeVar

T = TypeVar("T")


class Ok(TypedDict, Generic[T]):
    ok: Literal[True]
    value: T


class Err(TypedDict):
    ok: Literal[False]
    error: str


class _Invalid(Exception):
    def __init__(self, pos: int) -> None:
        super().__init__(f"invalid at {pos}")
        self.pos = pos


def _is_digit(ch: str | None) -> bool:
    return ch is not None and "0" <= ch <= "9"


class _Parser:
    """Collect integers and track the deepest list level."""

    def __init__(self, text: str) -> None:
        self.text = text
        self.pos = 0
        self.values: list[int] = []
        self.max_depth = 0

    def _peek(self) -> str | None:
        return self.text[self.pos] if self.pos < len(self.text) else None

    def _expect(self, ch: str) -> None:
        if self._peek() != ch:
            raise _Invalid(self.pos)
        self.pos += 1

    def parse(self) -> None:
        self._list(1)
        if self.pos != len(self.text):
            raise _Invalid(self.pos)

    def _list(self, depth: int) -> None:
        self._expect("[")
        level = depth
        self.max_depth = max(self.max_depth, level)
        state = "first"

        while True:
            ch = self._peek()
            if state != "separator":
                if ch == "[":
                    self.pos += 1
                    level += 1
                    self.max_depth = max(self.max_depth, level)
                    state = "first"
                    continue
                if state == "element" or ch != "]":
                    self._element(level)
                    state = "separator"
                    continue

            if ch == "]":
                self.pos += 1
                if level == depth:
                    return
                level -= 1
                state = "separator"
            elif ch == ",":
                self.pos += 1
                state = "element"
            else:
                raise _Invalid(self.pos)

    def _element(self, depth: int) -> None:
        if self._peek() == "[":
            self._list(depth + 1)
        else:
            self._integer()

    def _integer(self) -> None:
        negative = self._peek() == "-"
        if negative:
            self.pos += 1
        if not _is_digit(self._peek()):
            raise _Invalid(self.pos)

        value = 0
        while _is_digit(self._peek()):
            value = value * 10 + ord(self.text[self.pos]) - ord("0")
            self.pos += 1
        self.values.append(-value if negative else value)


def flatten_nested(s: str) -> Ok[tuple[list[int], int]] | Err:
    """Flatten a textual nested integer list and report its maximum depth."""
    parser = _Parser(s.replace(" ", ""))
    try:
        parser.parse()
    except _Invalid as exc:
        return {"ok": False, "error": str(exc)}
    return {"ok": True, "value": (parser.values, parser.max_depth)}

