    """Return the amount after the coupon, or an error message."""
    match coupon:
        case "":
            return subtotal
        case "SAVE500":
            return max(0, subtotal - 500)
        case "PCT10":
            return subtotal - subtotal // 10
        case "BIG20":
            if subtotal < 10000:
                return "coupon not applicable: BIG20"
            return subtotal - subtotal // 5
        case _:
            return f"unknown coupon: {coupon}"

