    }
  }
  let swapped = map(enumerate(suffix), |q| choose(q.0 == j, pivot, q.1))
  var out = append(take(xs, pivot_at), at(suffix, j))
  for x in reverse(swapped) {
    out = append(out, x)
  }
  return out
}

