    let tag = "line " + to_string(p.0 + 1) + ": "
    let cs = split(line, "")
    let head = unwrap_or(first(cs), "")
    if head == "[" {
      if len(cs) < 2 || unwrap_or(last(cs), "") != "]" {
        return Err(tag + "bad header")
      }
      let inner = cs
        |> drop(1)
        |> take(len(cs) - 2)
        |> join("")
        |> trim()
      if inner == "" {
        return Err(tag + "bad header")
      }
      section = inner
    } else if line != "" && head != "#" {
      let parts = split(line, "=")
      if len(parts) < 2 {
        return Err(tag + "missing =")
      }
      let key = parts
        |> first()
        |> unwrap_or("")
        |> trim()
      if key == "" {
        return Err(tag + "empty key")
      }
      let value = parts
        |> drop(1)
        |> join("=")
        |> trim()
      out = upsert(out, Setting { section: section, key: key, value: value })
    }
  }
  return Ok(out)
}

