type Employee = { name: string; dept: string; hours: number; rate_cents: number };

export function payroll_by_dept(emps: Employee[]): [string, number][] {
  const totals = new Map<string, number>();
  for (const e of emps) {
    const pay = e.hours <= 40
      ? e.hours * e.rate_cents
      : 40 * e.rate_cents + Math.floor(((e.hours - 40) * e.rate_cents * 3) / 2);
    totals.set(e.dept, (totals.get(e.dept) ?? 0) + pay);
  }

  return [...totals].sort(([deptA, payA], [deptB, payB]) => {
    if (payA !== payB) return payB - payA;

    let offset = 0;
    for (const char of deptA) {
      const a = char.codePointAt(0);
      const b = deptB.codePointAt(offset);
      if (b === undefined) return 1;
      if (a !== undefined && a !== b) return a - b;
      offset += char.length;
    }
    return offset < deptB.length ? -1 : 0;
  });
}

