export function payroll_by_dept(emps: Employee[]): [string, number][] {
  const totals = new Map<string, number>();
  for (const e of emps) {
    const pay = e.hours <= 40
      ? e.hours * e.rate_cents
      : 40 * e.rate_cents + Math.floor(((e.hours - 40) * e.rate_cents * 3) / 2);
    totals.set(e.dept, (totals.get(e.dept) ?? 0) + pay);
  }

  return [...totals].sort((a, b) => {
    const byPay = b[1] - a[1];
    if (byPay !== 0) return byPay;

    const left = Array.from(a[0]);
    const right = Array.from(b[0]);
    for (let i = 0; i < Math.min(left.length, right.length); i++) {
      const byCodePoint = left[i].codePointAt(0)! - right[i].codePointAt(0)!;
      if (byCodePoint !== 0) return byCodePoint;
    }
    return left.length - right.length;
  });
}

