fn robot_walk(cmds: List[Cmd], obstacles: List[(Int, Int)]) -> (Int, Int, String) {
  var x = 0
  var y = 0
  var d = 0
  for c in cmds {
    let steps = match c {
      Forward(k) => k,
      _ => 0,
    }
    d = match c {
      TurnLeft => (d + 3) % 4,
      TurnRight => (d + 1) % 4,
      _ => d,
    }
    let dv = delta(d)
    var k = 0
    while k < steps {
      let next = (x + dv.0, y + dv.1)
      if contains(obstacles, next) {
        k = steps
      } else {
        x = next.0
        y = next.1
        k = k + 1
      }
    }
  }
  let names = ["N", "E", "S", "W"]
  let direction = names
    |> drop(d)
    |> first()
    |> unwrap_or("N")
  return (x, y, direction)
}

