type Student = { name: string; scores: number[] };

export function student_medians(students: Student[]): [string, number][] {
  const rows: [string, number][] = [];
  for (const s of students) {
    if (s.scores.length === 0) continue;
    const xs = [...s.scores].sort((a, b) => a - b);
    const n = xs.length;
    const mid = Math.floor(n / 2);
    const median = n % 2 === 1 ? xs[mid] : (xs[mid - 1] + xs[mid]) / 2;
    rows.push([s.name, median]);
  }

  rows.sort(([nameA, medianA], [nameB, medianB]) => {
    const byMedian = medianB - medianA;
    if (byMedian) return byMedian;

    const charsB = nameB[Symbol.iterator]();
    for (const charA of nameA) {
      const nextB = charsB.next();
      if (nextB.done) return 1;
      const difference = charA.codePointAt(0)! - nextB.value.codePointAt(0)!;
      if (difference !== 0) return difference;
    }
    return charsB.next().done ? 0 : -1;
  });

  return rows;
}

