export function bank_ledger(ops: BankOp[]): Result<[string, number][]> {
  const bal = new Map<string, number>();
  for (let i = 0; i < ops.length; i++) {
    const op = ops[i];
    const fail = (msg: string): Result<[string, number][]> => ({ ok: false, error: "step " + (i + 1) + ": " + msg });
