  if d < 0 {
    return -1
  }
  return 1
}

fn normalize_part(p: String) -> String {
  let cs = split(p, "")
  for (i, c) in enumerate(cs) {
    if c != "0" {
      return join(drop(cs, i), "")
    }
  }
  return ""
}

