  return 1
}

fn normalize_part(p: String) -> String {
  let cs = split(p, "")
  for (i, c) in enumerate(cs) {
    if c != "0" {
      return join(drop(cs, i), "")
    }
  }
  return ""
}

fn normalized_part_at(ps: List[String], i: Int) -> String {
  return ps
    |> drop(i)
    |> first()
    |> unwrap_or("")
}

fn compare_versions(a: String, b: String) -> Result[Int, String] {
  if !valid_version(a) {
    return Err("bad version: " + a)
  }
  if !valid_version(b) {
    return Err("bad version: " + b)
  }
  let x = map(split(a, "."), normalize_part)
  let y = map(split(b, "."), normalize_part)
  for i in range(0, 4) {
    let p = normalized_part_at(x, i)
    let q = normalized_part_at(y, i)
    let d = str_len(p) - str_len(q)
    if d != 0 {
      return Ok(sign(d))
    }
    if p < q {
      return Ok(-1)
    }
    if p > q {
      return Ok(1)
    }
  }
  return Ok(0)
}

