from typing import Generic, Literal, TypedDict, TypeVar

T = TypeVar("T")


class Ok(TypedDict, Generic[T]):
    ok: Literal[True]
    value: T


class Err(TypedDict):
    ok: Literal[False]
    error: str


class _Invalid(Exception):
    def __init__(self, pos: int) -> None:
        super().__init__(f"invalid at {pos}")
        self.pos = pos


def _is_digit(ch: str | None) -> bool:
    return ch is not None and "0" <= ch <= "9"


class _Parser:
    """Collect integers and track the deepest list level."""

    def __init__(self, text: str) -> None:
        self.text = text
        self.pos = 0
        self.values: list[int] = []
        self.max_depth = 0

    def _peek(self) -> str | None:
        return self.text[self.pos] if self.pos < len(self.text) else None

    def _expect(self, ch: str) -> None:
        if self._peek() != ch:
            raise _Invalid(self.pos)
        self.pos += 1

    def parse(self) -> None:
        self._list(1)
        if self.pos != len(self.text):
            raise _Invalid(self.pos)

    def _list(self, depth: int) -> None:
        self._expect("[")
        self.max_depth = max(self.max_depth, depth)
        outer_depth = depth
        at_start = True

        while True:
            if at_start and self._peek() != "]":
                if self._peek() == "[":
                    self._element(depth)
                    depth += 1
                    continue
                self._element(depth)
                at_start = False

            if not at_start and self._peek() == ",":
                self.pos += 1
                if self._peek() == "[":
                    self._element(depth)
                    depth += 1
                    at_start = True
                else:
                    self._element(depth)
                continue

            self._expect("]")
            if depth == outer_depth:
                return
            depth -= 1
            at_start = False

    def _element(self, depth: int) -> None:
        if self._peek() == "[":
            self.pos += 1
            self.max_depth = max(self.max_depth, depth + 1)
        else:
            self._integer()

    def _integer(self) -> None:
        negative = self._peek() == "-"
        if negative:
            self.pos += 1
        if not _is_digit(self._peek()):
            raise _Invalid(self.pos)

        value = 0
        while _is_digit(self._peek()):
            value = value * 10 + ord(self.text[self.pos]) - ord("0")
            self.pos += 1
        self.values.append(-value if negative else value)


