fn at(cs: List[String], i: Int) -> String {
  return cs
    |> drop(i)
    |> first()
    |> unwrap_or("")
}

fn is_digit(c: String) -> Bool {
  return str_len(c) == 1 && c >= "0" && c <= "9"
}

fn unexpected(cs: List[String], i: Int) -> String {
  if i >= len(cs) {
    return "unexpected end"
  }
  return "unexpected character: " + at(cs, i)
}

fn parse_factor(cs: List[String], i: Int, evaluate: Bool) -> Result[(Int, Int, Bool), String] {
  if at(cs, i) == "(" {
    let r = try parse_expr(cs, i + 1, evaluate)
    if at(cs, r.1) != ")" {
      return Err(unexpected(cs, r.1))
    }
    return Ok((r.0, r.1 + 1, r.2))
  }
  if !is_digit(at(cs, i)) {
    return Err(unexpected(cs, i))
  }
  var j = i
  var n = 0
  while is_digit(at(cs, j)) {
    if evaluate {
      let digit = at(cs, j)
        |> parse_int()
        |> unwrap_or(0)
      n = n * 10 + digit
    }
    j = j + 1
  }
  return Ok((n, j, false))
}

fn parse_term(cs: List[String], i: Int, evaluate: Bool) -> Result[(Int, Int, Bool), String] {
  let f = try parse_factor(cs, i, evaluate)
  var v = f.0
  var j = f.1
  var z = f.2
  while at(cs, j) == "*" || at(cs, j) == "/" {
    let op = at(cs, j)
    let g = try parse_factor(cs, j + 1, evaluate && !z)
    z = z || g.2
    if evaluate && !z {
      if op == "*" {
        v = v * g.0
      } else if g.0 == 0 {
        z = true
      } else {
        v = v / g.0
      }
    }
    j = g.1
  }
  return Ok((v, j, z))
}

fn parse_expr(cs: List[String], i: Int, evaluate: Bool) -> Result[(Int, Int, Bool), String] {
  let f = try parse_term(cs, i, evaluate)
  var v = f.0
  var j = f.1
  var z = f.2
  while at(cs, j) == "+" || at(cs, j) == "-" {
    let op = at(cs, j)
    let g = try parse_term(cs, j + 1, evaluate && !z)
    z = z || g.2
    if evaluate && !z {
      if op == "+" {
        v = v + g.0
      } else {
        v = v - g.0
      }
    }
    j = g.1
  }
