  var a = 0
  var b = 0
  var c = 0
  var out = []
  for line in lines {
    let cs = split(line, "")
    let n = hashes(cs)
    let sp = cs
      |> drop(n)
      |> first()
      |> unwrap_or("")
    if n >= 1 && n <= 3 && sp == " " && len(cs) > n + 1 {
      let title = join(drop(cs, n + 1), "")
      if n == 1 {
        a = a + 1
        b = 0
        c = 0
        out = append(out, to_string(a) + " " + title)
      } else if n == 2 {
        b = b + 1
        c = 0
        out = append(out, to_string(a) + "." + to_string(b) + " " + title)
