    const right = b.sku[Symbol.iterator]();
    for (const left of a.sku) {
      const next = right.next();
      if (next.done) return 1;
      const diff = (left.codePointAt(0) ?? 0) - (next.value.codePointAt(0) ?? 0);
      if (diff !== 0) return diff;
    }
    return right.next().done ? 0 : -1;
  });
  return { ok: true, value: out };
}

