  if coupon == "SAVE500" {
    return Ok(max(sub, 500) - 500)
  }
  if coupon == "PCT10" {
    let discount = sub / 10
    if sub < discount * 10 {
      return Ok(sub - discount + 1)
    }
    return Ok(sub - discount)
  }
  if coupon == "BIG20" {
    if sub < 10000 {
