export function parse_duration(s: string): Result<number> {
  if (s === "") return { ok: false, error: "empty" };
  const units: Record<string, [number, number]> = { h: [0, 3600], m: [2, 60], s: [3, 1] };
  let total = 0;
  let digits = "";
  let last = -1;
  for (const c of s) {
    if (c >= "0" && c <= "9") {
      digits += c;
      continue;
