  let table = [(1000, "M"), (900, "CM"), (500, "D"), (400, "CD"), (100, "C"), (90, "XC"), (50, "L")]
  let small = [(40, "XL"), (10, "X"), (9, "IX"), (5, "V"), (4, "IV"), (1, "I")]
  var rest = n
  var out = ""
  for p in table {
    while rest >= p.0 {
      out = out + p.1
      rest = rest - p.0
    }
  }
  for p in small {
    while rest >= p.0 {
      out = out + p.1
      rest = rest - p.0
    }
  }
  return out
}

fn roman_to_int(s: String) -> Result[Int, String] {
  if s == "" {
    return Err("empty")
