type Instr =
  | Push(n: Int)
  | Pop
  | Add
  | Sub
  | Mul
  | Dup
  | Swap
  | Jz(target: Int)
  | Jmp(target: Int)
  | Print
  | Halt

fn needs(ins: Instr) -> Int {
  return match ins {
    Push(_) => 0,
    Pop => 1,
    Add => 2,
    Sub => 2,
    Mul => 2,
    Dup => 1,
    Swap => 2,
    Jz(_) => 1,
    Jmp(_) => 0,
    Print => 1,
    Halt => 0,
  }
}

fn jump_target(ins: Instr) -> Option[Int] {
  return match ins {
    Jz(t) => Some(t),
    Jmp(t) => Some(t),
    _ => None,
  }
}

fn stack_vm(prog: List[Instr]) -> Result[List[Int], String] {
  let n = len(prog)
  var stack = []
  var out = []
  var pc = 0
  var steps = 0
  while pc < n {
    if steps == 1000 {
      return Err("step limit exceeded")
    }
    steps = steps + 1
    let ins = prog
      |> drop(pc)
