type Student = { name: string; scores: number[] };

export function student_medians(students: Student[]): [string, number][] {
  const rows: [string, number][] = [];
  for (const s of students) {
    if (s.scores.length === 0) continue;
    const xs = [...s.scores].sort((a, b) => a - b);
    const n = xs.length;
    rows.push([s.name, n % 2 === 1 ? xs[(n - 1) / 2] : (xs[n / 2 - 1] + xs[n / 2]) / 2]);
  }

  rows.sort((a, b) => {
    const byMedian = b[1] - a[1];
    if (byMedian) return byMedian;

    const left = [...a[0]];
    const right = [...b[0]];
    for (let i = 0; i < Math.min(left.length, right.length); i++) {
      const byCodePoint = (left[i].codePointAt(0) ?? 0) - (right[i].codePointAt(0) ?? 0);
      if (byCodePoint !== 0) return byCodePoint;
    }
    return left.length - right.length;
  });

  return rows;
}

