fn tic_tac_toe(board: List[String]) -> String {
  let cells = split(join(board, ""), "")
  let nx = len(filter(cells, |c| c == "X"))
  let no = len(filter(cells, |c| c == "O"))
  let xw = has_line(cells, "X")
  let ow = has_line(cells, "O")
  if nx != no && nx != no + 1 {
    return "invalid"
  }
  if xw && ow {
    return "invalid"
  }
  if xw && nx != no + 1 {
    return "invalid"
  }
  if ow && nx != no {
    return "invalid"
  }
  if xw {
    return "X wins"
  }
  if ow {
    return "O wins"
  }
  if nx + no == 9 {
    return "draw"
  }
  return "in progress"
}

