        if ch == " ":
            i += 1
        elif _is_digit(ch):
            end = _scan_while(s, i, _is_digit)
            tokens.append({"kind": "Num", "value": int(s[i:end])})
            i = end
        elif _is_ident_start(ch):
            end = _scan_while(s, i, _is_ident_char)
            tokens.append({"kind": "Ident", "name": s[i:end]})
            i = end
