export function competition_rank(players: Player[]): [number, string][] {
  const sorted = [...players].sort((a, b) => {
    if (a.score !== b.score) return b.score - a.score;

    let i = 0;
    while (i < a.name.length && i < b.name.length) {
      const left = a.name.codePointAt(i) ?? 0;
      const right = b.name.codePointAt(i) ?? 0;
      if (left !== right) return left - right;
      i += left > 0xffff ? 2 : 1;
    }
    return a.name.length - b.name.length;
  });

  let rank = 0;
  return sorted.map((player, i): [number, string] => {
    if (i === 0 || player.score !== sorted[i - 1].score) {
      rank = i + 1;
    }
    return [rank, player.name];
  });
}

