fn term(cs: List[String], i: Int) -> Result[(Int, Int, Bool), String] {
  let f = try factor(cs, i)
  var v = f.0
  var j = f.1
  var z = f.2
  while at(cs, j) == "*" || at(cs, j) == "/" {
    let op = at(cs, j)
    let g = try factor(cs, j + 1)
    if op == "*" {
      v = v * g.0
    } else if g.0 == 0 {
      z = true
      v = 0
    } else {
      v = v / g.0
    }
    z = z || g.2
    j = g.1
  }
  return Ok((v, j, z))
}

fn expr(cs: List[String], i: Int) -> Result[(Int, Int, Bool), String] {
  let f = try term(cs, i)
  var v = f.0
  var j = f.1
  var z = f.2
  while at(cs, j) == "+" || at(cs, j) == "-" {
    let op = at(cs, j)
    let g = try term(cs, j + 1)
    if op == "+" {
      v = v + g.0
    } else {
      v = v - g.0
    }
    z = z || g.2
    j = g.1
  }
  return Ok((v, j, z))
}

fn eval_expr(s: String) -> Result[Int, String] {
  let cs = filter(split(s, ""), |c| c != " ")
  var depth = 0
  var needs_factor = true
  var in_number = false
  for (i, c) in enumerate(cs) {
    if is_digit(c) && (needs_factor || in_number) {
      needs_factor = false
      in_number = true
    } else {
      in_number = false
      let is_operator = c == "+" || c == "-" || c == "*" || c == "/"
      if needs_factor && c == "(" {
        depth = depth + 1
      } else if !needs_factor && is_operator {
        needs_factor = true
      } else if !needs_factor && c == ")" && depth > 0 {
        depth = depth - 1
      } else {
        return Err(unexpected(cs, i))
      }
    }
  }
  if needs_factor || depth > 0 {
    return Err(unexpected(cs, len(cs)))
  }
  let r = try expr(cs, 0)
  if r.2 {
    return Err("division by zero")
  }
  return Ok(r.0)
}

