  for (let a = 1; a <= amount; a++) {
    let b: number | null = null;
    for (const c of coins) {
      const p = a - c >= 0 ? best[a - c] : null;
      if (p !== null && p !== undefined && (b === null || p + 1 < b)) b = p + 1;
    }
    best.push(b);
  }
  if (best[amount] === null) return null;
  const used: number[] = [];
