fn upsert(xs: List[Setting], s: Setting) -> List[Setting] {
  var found = false
  var out = []
  for x in xs {
    if x.section == s.section && x.key == s.key {
      out = append(out, s)
      found = true
    } else {
      out = append(out, x)
    }
  }
  if !found {
