type Employee {
  name: String,
  dept: String,
  hours: Int,
  rate_cents: Int,
}

fn pay(e: Employee) -> Int {
  if e.hours <= 40 {
    return e.hours * e.rate_cents
  }
  let regular = 40 * e.rate_cents
  let overtime_base = (e.hours - 40) * e.rate_cents
  var half = overtime_base / 2
  if overtime_base % 2 < 0 {
    half = half - 1
  }
  return regular + overtime_base + half
}

fn payroll_by_dept(emps: List[Employee]) -> List[(String, Int)] {
  return emps
