  var out = ""
  var ch = ""
  var have = false
  var digits = ""
  for c in split(s, "") {
    if is_digit(c) {
      if !have {
        return Err("missing character before count")
      }
      digits = digits + c
    } else {
      if have {
        out = try flush(out, ch, digits)
      }
      ch = c
      have = true
      digits = ""
    }
  }
  if have {
    out = try flush(out, ch, digits)
  }
  return Ok(out)
}

