type Session {
  user: String,
  kind: String,
  time: Int,
}

fn user_total(evs: List[Session], end: Int) -> Int {
  var total = 0
  var since = 0
  var inside = false
  for e in evs {
    if e.kind == "login" && !inside {
      inside = true
      since = e.time
    } else if e.kind == "logout" && inside {
      inside = false
      total = total + (e.time - since)
    }
  }
  if inside {
    total = total + (end - since)
  }
  return total
