type Session = { user: string; kind: string; time: number };

export function session_totals(events: Session[]): [string, number][] {
  const totals = new Map<string, number>();
  const open = new Map<string, number>();

  for (const e of events) {
    if (!totals.has(e.user)) totals.set(e.user, 0);
    if (e.kind === "login") {
      if (!open.has(e.user)) open.set(e.user, e.time);
    } else {
      const start = open.get(e.user);
      if (start !== undefined) {
        totals.set(e.user, totals.get(e.user)! + (e.time - start));
        open.delete(e.user);
      }
    }
  }

  const end = events.length ? events[events.length - 1].time : 0;
  for (const [user, start] of open) {
    totals.set(user, totals.get(user)! + (end - start));
  }

  return [...totals].sort(([a], [b]) => {
    const right = b[Symbol.iterator]();
    for (const char of a) {
      const next = right.next();
      if (next.done) return 1;
      const difference = char.codePointAt(0)! - next.value.codePointAt(0)!;
      if (difference !== 0) return difference;
    }
    return right.next().done ? 0 : -1;
  });
}

