from typing import Generic, Literal, TypedDict, TypeVar
from collections.abc import Callable

T = TypeVar("T")


class Ok(TypedDict, Generic[T]):
    ok: Literal[True]
    value: T


class Err(TypedDict):
    ok: Literal[False]
    error: str


class Num(TypedDict):
    kind: Literal["Num"]
    value: int


class Ident(TypedDict):
    kind: Literal["Ident"]
    name: str


class Sym(TypedDict):
    kind: Literal["Sym"]
    text: str


Token = Num | Ident | Sym


