    """Greedily wrap words without splitting words longer than width."""
    lines: list[str] = []
    current = ""
    for word in s.split(" "):
        if not word:
            continue
        if not current:
            current = word
        elif len(current) + 1 + len(word) <= width:
            current = f"{current} {word}"
        else:
            lines.append(current)
            current = word
    if current:
